<?php/** * 短信服务 */namespace app\api\service\public;use app\api\service\CommService;use app\common\Env;use Lianlu\Lianlu\Clients\SmsSend;use Lianlu\Lianlu\Common\Credential;use Lianlu\Lianlu\models\Sms;use support\Cache;use support\exception\BusinessException;class SmsService extends CommService{    const expiry_time = 300;    public function __construct($param)    {        parent::_initialize($param);        Env::loadFile($_SERVER['ROOT_DIR'] . '.envsms');    }    public function verificationCode($mobile, $code)    {        if (!$this->is_debug) {            $cache_code = Cache::get($mobile);            Cache::delete($mobile);            if ($cache_code != $code) {                throw new BusinessException('验证码错误', 401);            }        }        return true;    }    public function getCode()    {        $cred = new Credential(            Env::get('sms.mch_id'),            Env::get('sms.app_id'),            Env::get('sms.app_key')        );        $random = mt_rand(100000, 999999);        // send template sms        $input = new Sms();        $input->SetTemplateId(Env::get('sms.template_id'));        $input->SetPhoneNumberSet($this->param['mobile']);        $input->SetTemplateParamSet([$random]);//dd($input);        $res = json_decode(SmsSend::TemplateSend($cred, $input), true);//dd($res);        if ($res['status'] == '00') {            Cache::set($this->param['mobile'], $random, self::expiry_time);            return $this->data;        }        throw new BusinessException($res['message'], 401);    }}